      "ja": "殺生物剤，有害生物忌避剤または誘引剤または植物生長調節剤であって，その形態，またはその不活性成分または使用法に特徴があるもの；活性成分による有害生物以外の生物への悪影響を低減するための物質［２００６．０１］",
      "en": "Biocides, pest repellants or attractants, or plant growth regulators, characterised by their forms, or by their non-active ingredients or by their methods of application; Substances for reducing the noxious effect of the active ingredients to organisms other than pests [2006.01]",
