      "level": 1,
      "parent": "A01N25/00\\",
      "ja": "不活性成分により特徴づけられるもの〔２５／０２～２５／３４に分類されないもの〕〔粘着性捕そく剤：薬効増強剤，植物細胞膜透過性への影響物質，保湿成分，肥料を含む農薬：種子コ－テイング剤中に含まれる農薬〕〔効力増強が植物への展着性によるもの→２５／２４〕",
      "en": "Characterized by inert ingredients (not categorized between 25/02 to 25/34) (adhesive capturing agents: medicinal properties enhancing agents, materials influencing the permeability of plant cell membranes, water holding ingredients, agricultural chemicals including fertilizers: agricultural chemicals contained in seed coating agents) (medical propaties are enhanced by the spreading to plantsR25/24 )",
      "count": 2020,
