      "level": 1,
      "parent": "A01N37/00\\",
      "ja": "少なくとも１個のカルボキシル基，そのチオ類似体またはその誘導体を含み，酸素または硫黄原子が単結合で同一炭素骨格についているもの，この酸素または硫黄原子はカルボキシル基，チオ類似体またはその誘導体の１員ではない，例．ヒドロキシカルボン酸［３］",
      "en": "containing at least one carboxylic group or a thio-analogue, or a derivative thereof, and a singly bound oxygen or sulfur atom attached to the same carbon skeleton, this oxygen or sulfur atom not being a member of a carboxylic group or of a thio-analogue, or of a derivative thereof, e.g. hydroxy-carboxylic acids [3]",
