    "A01N43/00\\": {
      "code": "A01N43/00\\",
      "level": 0,
      "parent": null,
      "ja": "殺生物剤，有害生物忌避剤または誘引剤，または植物生長調節剤であって複素環式化合物を含むもの（環式無水物，環式イミドを含むものＡ０１Ｎ３７／００；ただ１個の複素環を有する式「図」の化合物を含むもの，ここでｍ≧１，ｎ≧０であり，「図」は非置換またはアルキル置換したピロリジン，ピペリジン，モルホリン，チオモルホリン，ピペラジンまたは４個またはそれ以上のＣＨ２基を有するポリメチレンイミンＡ０１Ｎ３３／００～Ａ０１Ｎ４１／１２；シクロプロパンカルボン酸またはその誘導体，例．複素環を持つエステル，を含むものＡ０１Ｎ５３／００）［３］",
      "en": "Biocides, pest repellants or attractants, or plant growth regulators containing heterocyclic compounds (containing cyclic anhydrides, cyclic imides A01N37/00; containing compounds of the formula , containing only one heterocyclic ring, wherein m?1 and n?0 and  is unsubstituted or alkylsubstituted pyrrolidine, piperidine, morpholine, thiomorpholine, piperazine or a polymethyleneimine with four or more CH2 groups A01N33/00-A01N41/12; containing cyclopropane carboxylic acids or derivatives thereof, e.g. esters having heterocyclic rings, A01N53/00) [3]",
      "count": 114,
      "ipcCode": "A01N43/00",
      "fTerm": "4H011",
      "childFlag": 0,
      "sourceFile": "fi_A01N.txt",
      "kind": "fi"
    },
