      "level": 0,
      "parent": null,
      "ja": "少なくとも１つの環が６員環ではなく，相互に縮合した３つ以上の炭素環を有する化合物を含有している殺生物剤，有害生物忌避剤または誘引剤，または植物生長調節剤（ハロゲン化炭化水素Ａ０１Ｎ２９／０８；複素環と縮合したものＡ０１Ｎ４３／００）［３］",
      "en": "Biocides, pest repellants or attractants, or plant growth regulators containing compounds having three or more carbocyclic rings condensed among themselves, at least one ring not being a six-membered ring (halogenated hydrocarbons A01N 29/08; condensed with heterocyclic rings A01N 43/00) [3]",
      "count": 165,
      "ipcCode": "A01N45/00",
      "fTerm": "4H011",
      "childFlag": 0,
