    "A01N49/00\\": {
      "code": "A01N49/00\\",
      "level": 0,
      "parent": null,
      "ja": "次のいずれかの基を含む化合物を含有している殺生物剤，有害生物忌避剤または誘引剤，または植物生長調節剤，例．幼若昆虫ホルモンまたはそれの類似体（炭化水素を含むものＡ０１Ｎ２７／００）「図」上式において，ｍ＋ｎ≧１であり，２つのＸはいっしょになって―Ｙ―または直接炭素―炭素結合を意味することもあり，星印のついている炭素原子は，２つの原子Ｘによって形成されることのある環系の場合を除いて，いかなる環系の一部でもなく，角かっこの中の炭素原子は，非環式または環式構造の一部である。「図」上式においては，Ａは１つの炭素原子またはＹを意味し，ｎ≧０であり，これらの炭素原子のうち２つ以上の炭素原子が同じ環系の一部であることはない。［３］",
      "en": "Biocides, pest repellants or attractants, or plant growth regulators containing compounds containing the group [figure] wherein m+n&ge;1, both X together may also mean &mdash;Y&mdash; or a direct carbon-to-carbon bond, and the carbon atoms marked with an asterisk are not part of any ring system other than that which may be formed by the atoms X, the carbon atoms in square brackets being part of any acyclic or cyclic structure, or the group [figure] wherein A means a carbon atom or Y, n &ge; 0, and not more than one of these carbon atoms being a member of the same ring system, e.g. juvenile insect hormones or mimics thereof (containing hydrocarbons A01N 27/00) [3]",
      "count": 141,
      "ipcCode": "A01N49/00",
      "fTerm": "4H011",
      "childFlag": 0,
      "sourceFile": "fi_A01N.txt",
      "kind": "fi"
    },
    "A01N51/00\\": {
      "code": "A01N51/00\\",
      "level": 0,
      "parent": null,
      "ja": "殺生物剤，有害生物忌避剤または誘引剤，または植物生長調節剤であって，各原子が有する結合の数に関係なくまたこの配列の原子が複素環の１部でないＯ―Ｎ―Ｓ，Ｘ―Ｏ―Ｓ，Ｎ―Ｎ―Ｓ，Ｏ―Ｎ―ＮまたはＯ―ハロゲンの原子配列を有する有機化合物を含むもの［３］",
      "en": "Biocides, pest repellants or attractants, or plant growth regulators containing organic compounds having the sequences of atoms O&mdash;N&mdash;S, X&mdash;O&mdash;S, N&mdash;N&mdash;S, O&mdash;N&mdash;N or O-halogen, regardless of the number of bonds each atom has and with no atom of these sequences forming part of a heterocyclic ring [3]",
      "count": 1443,
      "ipcCode": "A01N51/00",
      "fTerm": "4H011",
      "childFlag": 0,
      "sourceFile": "fi_A01N.txt",
      "kind": "fi"
    },
