      "code": "A01N53/00\\",
      "level": 0,
      "parent": null,
      "ja": "殺生物剤，有害生物忌避剤または誘引剤，または植物生長調節剤であってシクロプロパンカルボン酸またはその誘導体を含むもの［３］",
      "en": "Biocides, pest repellants or attractants, or plant growth regulators containing cyclopropane carboxylic acids or derivatives thereof [3]",
